    const spent=(cats)=>tx.filter(x=>x.kind==='out'&&cats.includes(x.category)).reduce((a,x)=>a+Number(x.amount||0),0);
    const needs=spent(['Moradia','Alimentação','Transporte','Saúde','Educação','Contas essenciais']);
