  function nutritionDetailsHTML(x){if(!x)return '';const catalog=x.barcode&&data.productCatalog?data.productCatalog[x.barcode]:null;const n=x.nutrition||{};const p={...(catalog||{}),name:x.name||catalog?.name||'Produto sem nome',brand:catalog?.brand||'',quantity:x.qty||catalog?.quantity||'',barcode:x.barcode||catalog?.barcode||'',kcal:n.kcal??catalog?.kcal??null,sugars:n.sugars??catalog?.sugars??null,satFat:n.satFat??catalog?.satFat??null,sodium:n.sodium??catalog?.sodium??null,protein:n.protein??catalog?.protein??null,grade:n.grade||catalog?.grade||''};p.rating=evaluateProduct(p);return `<div class="nutrition-modal-backdrop" data-close-nutrition><section class="nutrition-modal" role="dialog" aria-modal="true" aria-labelledby="nutrition-title"><div class="nutrition-modal-head"><div><h3 id="nutrition-title">Informações do produto</h3><strong>${esc(p.name)}</strong><p class="muted">${esc([p.brand,p.quantity,p.barcode?'Código '+p.barcode:''].filter(Boolean).join(' · '))}</p></div><button class="btn" type="button" data-close-nutrition aria-label="Fechar informações">Fechar ✕</button></div><div class="grid"><div><div class="muted">Energia</div><strong>${fmtN(p.kcal,' kcal/100 g')}</strong></div><div><div class="muted">Açúcares</div><strong>${fmtN(p.sugars,' g/100 g')}</strong></div><div><div class="muted">Gordura saturada</div><strong>${fmtN(p.satFat,' g/100 g')}</strong></div><div><div class="muted">Sódio</div><strong>${fmtN(p.sodium,' mg/100 g')}</strong></div><div><div class="muted">Proteína</div><strong>${fmtN(p.protein,' g/100 g')}</strong></div><div><div class="muted">Nutri-Score</div><strong>${esc(p.grade?p.grade.toUpperCase():'Não informado')}</strong></div></div><div class="notice" style="margin-top:14px"><strong>${esc(p.rating.title)}</strong><p style="margin:6px 0 0">${esc(p.rating.text)}</p></div><p class="muted">Valores nutricionais geralmente são por 100 g ou 100 ml e podem estar ausentes ou desatualizados. Confira sempre a embalagem.</p></section></div>`}
