  const showAuth=(message='')=>{ $('#authGate').classList.remove('hidden','checking'); $('#authStatus').textContent=message; $('#logoutBtn').classList.add('hidden'); $('#accountLabel').textContent=''; };
  const hideAuth=()=>$('#authGate').classList.add('hidden');
  const loadUserData=async(user)=>{
    if(!user||!acceptedTerms)return;
    if(cloudReady&&currentUser?.uid===user.uid)return;
    if(loadingUid===user.uid)return;
    loadingUid=user.uid;cloudReady=false;
    if(cloudUnsubscribe){cloudUnsubscribe();cloudUnsubscribe=null}
    currentUser=user;activeDataKey='equilibrio-v1-data-'+user.uid;
    let local={};try{local=JSON.parse(localStorage.getItem(activeDataKey)||'{}')||{}}catch{local={}}
    // Keep the original local-only records as a candidate for a one-time cloud migration.
    const legacyRaw=localStorage.getItem(LEGACY_KEY);
    if(!Object.keys(local).length&&legacyRaw){let legacy;try{legacy=JSON.parse(legacyRaw)}catch{legacy=null}if(legacy&&confirm('Encontramos registros antigos do Equilíbrio neste navegador, ainda não vinculados à sua conta. Deseja incluí-los na sincronização desta conta Google? Eles serão enviados ao Firebase.'))local=legacy;}
    data={...blank(),...local};
    $('#accountLabel').textContent=(user.displayName||user.email||'Conta Google')+' · conectando…';
    $('#logoutBtn').classList.remove('hidden');render();
    try{
      cloudDoc=firebase.firestore().collection('users').doc(user.uid).collection('appData').doc('main');
      const snap=await cloudDoc.get();
      if(currentUser?.uid!==user.uid)return;
      if(snap.exists){
        data=mergeLocalAndCloud(snap.data()?.data||{},local);
      }else{
        data={...blank(),...local};
      }
      localStorage.setItem(activeDataKey,JSON.stringify(data));
      cloudReady=true;
      await cloudDoc.set({data:JSON.parse(JSON.stringify(data)),updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
      cloudUnsubscribe=cloudDoc.onSnapshot(snapshot=>{
        if(!snapshot.exists||!currentUser||currentUser.uid!==user.uid)return;
        const remote=snapshot.data()?.data;
        if(remote&&typeof remote==='object'){
          data={...blank(),...remote};
          localStorage.setItem(activeDataKey,JSON.stringify(data));
          render();
        }
      },err=>{console.error('Erro no listener de sincronização:',err);if($('#accountLabel'))$('#accountLabel').textContent=(user.displayName||user.email||'Conta Google')+' · sincronização indisponível';});
      $('#accountLabel').textContent=(user.displayName||user.email||'Conta Google')+' · sincronizado';render();hideAuth();
    }catch(err){
      cloudReady=false;cloudDoc=null;
      console.error('Falha ao conectar com Firestore:',err);
      showAuth('Não foi possível ativar a sincronização. Confira se o Firestore foi criado e se as regras de segurança foram publicadas. Código: '+(err.code||err.message||'erro desconhecido'));
    }finally{loadingUid=null}
  };
