  const authError=(err)=>{const code=err&&err.code||'';if(code==='auth/unauthorized-domain')return 'Domínio não autorizado no Firebase. Em Authentication → Settings → Authorized domains, confirme equilbrioappbr.github.io.';if(code==='auth/operation-not-allowed')return 'O login Google não está habilitado no Firebase. Confira Authentication → Sign-in method.';if(code==='auth/unauthorized-continue-uri')return 'O endereço de retorno não está autorizado no Firebase.';if(code==='auth/popup-blocked')return 'O navegador bloqueou a janela de autenticação. Permita pop-ups e tente novamente.';if(code==='auth/network-request-failed')return 'Falha de conexão durante a autenticação. Confira a internet e tente novamente.';return 'Falha no login Google: '+(code||err?.message||'erro desconhecido')+'. Confira as configurações e tente novamente.'};
